def reward_intermediate_calculation_accuracy(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for prompt, completion, true_answer in zip(prompts, completions, answer):
        response = completion[0]['content']
        thinking = extract_thinking(response)
        if not thinking:
            scores.append(-1.0)
            continue

        # Find simple arithmetic expressions: A op B = C
        # Regex for numbers and operators
        pattern = r'(-?\d+\.?\d*)\s*([+\-*/])\s*(-?\d+\.?\d*)\s*=\s*(-?\d+\.?\d*)'
        matches = re.findall(pattern, thinking)

        if not matches:
            # No explicit calculations found, neutral score
            scores.append(0.0)
            continue

        errors = 0
        total = len(matches)

        for a, op, b, c in matches:
            try:
                a_val = float(a)
                b_val = float(b)
                c_val = float(c)

                if op == '+':
                    calc = a_val + b_val
                elif op == '-':
                    calc = a_val - b_val
                elif op == '*':
                    calc = a_val * b_val
                elif op == '/':
                    if b_val == 0:
                        errors += 1
                        continue
                    calc = a_val / b_val

                # Allow small floating point error
                if abs(calc - c_val) > 1e-6:
                    errors += 1
            except:
                errors += 1

        # Calculate score based on error rate
        if total == 0:
            scores.append(0.0)
        else:
            error_rate = errors / total
            if error_rate == 0:
                scores.append(3.0)
            elif error_rate < 0.2:
                scores.append(1.0)
            elif error_rate < 0.5:
                scores.append(-1.0)
            else:
                scores.append(-2.0)
    return scores

def reward_problem_identification(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for prompt, completion, true_answer in zip(prompts, completions, answer):
        response = completion[0]['content']
        thinking = extract_thinking(response)
        if not thinking:
            scores.append(-1.0)
            continue

        prompt_text = prompt[0]['content'] if prompt else ''

        # Identify problem type keywords
        problem_types = {
            'geometry': ['triangle', 'circle', 'square', 'rectangle', 'angle', 'diagram', 'figure', 'asy'],
            'algebra': ['equation', 'solve for', 'x =', 'y =', 'polynomial', 'factor'],
            'probability': ['probability', 'chance', 'dice', 'coin', 'expected value'],
            'number_theory': ['divisible', 'prime', 'factor', 'integer', 'multiple'],
            'calculus': ['derivative', 'integral', 'limit', 'slope']
        }

        detected_types = []
        for ptype, keywords in problem_types.items():
            if any(kw in prompt_text.lower() for kw in keywords):
                detected_types.append(ptype)

        if not detected_types:
            scores.append(0.0)
            continue

        # Check if thinking mentions the correct type
        thinking_lower = thinking.lower()
        mentioned_types = []
        for ptype, keywords in problem_types.items():
            if any(kw in thinking_lower for kw in keywords):
                mentioned_types.append(ptype)

        score = 0.0

        # Reward if at least one detected type is mentioned
        if detected_types and mentioned_types:
            if set(detected_types).intersection(mentioned_types):
                score += 2.0
            else:
                score -= 1.0 # Mentioned wrong type

        # Bonus for explicitly stating the problem type
        if 'problem' in thinking_lower and ('is a' in thinking_lower or 'involves' in thinking_lower):
            score += 1.0

        scores.append(max(-2.0, min(5.0, score)))
    return scores
